window.kbPageData["views/entry/k-362c159c0d3ed6cb"] = {"key":"entry/k-362c159c0d3ed6cb","state":{"route":"entry/k-362c159c0d3ed6cb"},"node":{"id":"k-362c159c0d3ed6cb","mode":"k","title":"新时代“枫桥经验”","type":"观点与论证","domain":"社会治理","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["governance"],"主类":["观点与论证"],"出处性质":["机构注释"],"学科":["社会治理"],"来源主题":["发展与治理"],"资料类别":["非时政"]},"directorySummary":"3.新时代“枫桥经验”\n（1）“枫桥经验”\n“枫桥经验”是指 20 世纪 60 年代初，浙江诸暨县（现诸暨市）枫桥镇干部群众创造的\n“发动和依靠群众，坚持矛盾不上交，就地解决，实现捕人少，治安好”的基层社会治理经\n验。\n1963 年，毛泽东同志亲笔批示：“要各地仿效，经过试点，推广去做。”2003 …","sources":[{"id":"2749f538678c62c3","label":"新时代“枫桥经验”","topic":"发展与治理","category":"非时政","text":"3.新时代“枫桥经验”\n（1）“枫桥经验”\n“枫桥经验”是指 20 世纪 60 年代初，浙江诸暨县（现诸暨市）枫桥镇干部群众创造的\n“发动和依靠群众，坚持矛盾不上交，就地解决，实现捕人少，治安好”的基层社会治理经\n验。\n1963 年，毛泽东同志亲笔批示：“要各地仿效，经过试点，推广去做。”2003 年，时\n任浙江省委书记的习近平同志明确要求充分珍惜、大力推广、不断创新“枫桥经验”。\n（2）新时代“枫桥经验”\n“枫桥经验”在实践中不断丰富、持续发展，特别是党的十八大以来，形成了特色鲜明\n的新时代“枫桥经验”。\n党的十八大以来，习近平总书记多次作出重要指示，要求在社会基层坚持和发展新时代\n“枫桥经验”。其内涵是：坚持和贯彻党的群众路线，在党的领导下，充分发动群众、组织\n群众、依靠群众解决群众自己的事情，做到“小事不出村、大事不出镇、矛盾不上交”。","source":{"doc":"6cbfb01fe723bba64b75","first":50,"last":50,"page":50,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"governance","title":"基层治理与群众参与"}],"units":{"k-362c159c0d3ed6cb":[]}};
